#!/bin/bash
# Monitor settings. Every change regenerates ~/.config/hypr/monitors.lua
# from the live layout, reloads Hyprland, and reverts unless confirmed.
# Rules for monitors that aren't plugged in are kept for their next return.
#
#   displays-menu.sh --print [CHANGE]   print the generated file, apply nothing

source "$HOME/.config/hypr/scripts/menu-lib.sh"

MENU_TITLE="sobarch: displays"
MENU_ICON="devices.svg"

MONITORS_LUA="$HOME/.config/hypr/monitors.lua"
LOCAL_LUA="$HOME/.config/hypr/local.lua"
SEP=$'\x1f'

# Parallel arrays indexed by monitor, read from `hyprctl monitors all`.
load_monitors() {
    M_NAME=() M_DESC=() M_W=() M_H=() M_REFRESH=() M_X=() M_Y=()
    M_SCALE=() M_TRANSFORM=() M_OFF=() M_MIRROR=() M_MODES=()
    local name desc w h refresh x y scale transform off mirror modes
    while IFS="$SEP" read -r name desc w h refresh x y scale transform off mirror modes; do
        M_NAME+=("$name") M_DESC+=("$desc") M_W+=("$w") M_H+=("$h")
        M_REFRESH+=("$refresh") M_X+=("$x") M_Y+=("$y") M_SCALE+=("$scale")
        M_TRANSFORM+=("$transform") M_OFF+=("$off") M_MIRROR+=("$mirror")
        M_MODES+=("$modes")
    done < <(hyprctl monitors all | awk -v sep="$SEP" '
        function flush() {
            if (name == "") return
            printf "%s", name sep desc sep w sep h sep sprintf("%.2f", r) sep x sep y sep scale sep tr sep off sep mirror sep modes "\n"
        }
        /^Monitor / { flush(); name = $2; desc = ""; w = h = r = x = y = tr = off = 0; scale = 1; mirror = ""; modes = ""; next }
        /^\t[0-9]+x[0-9]+@/ {
            split($1, a, "@"); split(a[1], wh, "x"); w = wh[1]; h = wh[2]; r = a[2]
            split($3, p, "x"); x = p[1]; y = p[2]; next
        }
        /^\tdescription: / { desc = substr($0, 15); next }
        /^\tscale: / { scale = $2; next }
        /^\ttransform: / { tr = $2; next }
        /^\tdisabled: / { off = ($2 == "true"); next }
        /^\tmirrorOf: / { mirror = ($2 == "none" ? "" : $2); next }
        /^\tavailableModes: / { sub(/^\tavailableModes: /, ""); gsub(/Hz/, ""); modes = $0; next }
        END { flush() }')
}

# Logical size after scale and rotation, as "W H".
logical_size() {
    local i=$1
    awk -v w="${M_W[$i]}" -v h="${M_H[$i]}" -v s="${M_SCALE[$i]}" -v t="${M_TRANSFORM[$i]}" '
        BEGIN {
            if (t % 2 == 1) { x = w; w = h; h = x }
            printf "%d %d", w / s + 0.5, h / s + 0.5
        }'
}

lua_escape() { local s=${1//\\/\\\\}; printf '%s' "${s//\"/\\\"}"; }

# Prints one hl.monitor block for monitor $1.
emit_block() {
    local i=$1 out
    out="desc:$(lua_escape "${M_DESC[$i]}")"
    if ((M_OFF[i])); then
        printf 'hl.monitor({\n\toutput = "%s",\n\tdisabled = true,\n})\n\n' "$out"
        return
    fi
    printf 'hl.monitor({\n\toutput = "%s",\n' "$out"
    if ((M_W[i] == 0)); then
        printf '\tmode = "preferred",\n\tposition = "auto",\n'
    elif [ -n "${M_MIRROR[$i]}" ]; then
        printf '\tmirror = "%s",\n' "${M_MIRROR[$i]}"
    else
        printf '\tmode = "%sx%s@%s",\n\tposition = "%sx%s",\n' "${M_W[$i]}" "${M_H[$i]}" "${M_REFRESH[$i]}" "${M_X[$i]}" "${M_Y[$i]}"
    fi
    printf '\tscale = %s,\n\ttransform = %s,\n})\n\n' "${M_SCALE[$i]}" "${M_TRANSFORM[$i]}"
}

# Blocks from the existing file whose monitor isn't connected right now.
keep_absent_blocks() {
    [ -f "$MONITORS_LUA" ] || return 0
    local present="" i
    for i in "${!M_NAME[@]}"; do present+="desc:$(lua_escape "${M_DESC[$i]}")$SEP"; done
    awk -v present="$present" -v sep="$SEP" '
        /^hl\.monitor\(\{/ { inblock = 1; block = "" }
        inblock {
            block = block $0 "\n"
            if ($0 ~ /^\toutput = "/) { out = $0; sub(/^\toutput = "/, "", out); sub(/",$/, "", out) }
            if ($0 ~ /^\}\)/) {
                inblock = 0
                if (index(sep present, sep out sep) == 0) printf "%s\n", block
            }
        }' "$MONITORS_LUA"
}

generate() {
    echo "-- Generated by the Displays menu; changes made here are overwritten."
    echo "-- Put hand-written monitor rules in local.lua, which is loaded after this."
    echo
    local i
    for i in "${!M_NAME[@]}"; do emit_block "$i"; done
    keep_absent_blocks
}

# Move every enabled, non-mirrored monitor so the layout starts at 0x0.
normalize_positions() {
    local i minx="" miny=""
    for i in "${!M_NAME[@]}"; do
        ((M_OFF[i])) && continue
        [ -n "${M_MIRROR[$i]}" ] && continue
        [ -z "$minx" ] || ((M_X[i] < minx)) && minx=${M_X[$i]}
        [ -z "$miny" ] || ((M_Y[i] < miny)) && miny=${M_Y[$i]}
    done
    [ -n "$minx" ] || return 0
    for i in "${!M_NAME[@]}"; do
        ((M_OFF[i])) && continue
        M_X[i]=$((M_X[i] - minx))
        M_Y[i]=$((M_Y[i] - miny))
    done
}

enabled_count() {
    local i n=0
    for i in "${!M_NAME[@]}"; do ((M_OFF[i])) || n=$((n + 1)); done
    echo "$n"
}

# Reload Hyprland with the new file; revert unless the user confirms.
apply() {
    local new backup=""
    new=$(mktemp)
    generate >"$new"
    [ -f "$MONITORS_LUA" ] && { backup=$(mktemp); cp "$MONITORS_LUA" "$backup"; }
    mv "$new" "$MONITORS_LUA"
    chmod 644 "$MONITORS_LUA"
    hyprctl reload >/dev/null
    sleep 1

    # timeout kills the whole group, fuzzel included, so a blank screen
    # can't strand the user.
    if timeout 15 bash -c "source '$MENU_SCRIPTS/confirm.sh'; confirm 'Keep these display settings? Reverting in 15 seconds.' Keep"; then
        [ -n "$backup" ] && rm -f "$backup"
        return 0
    fi
    if [ -n "$backup" ]; then
        mv "$backup" "$MONITORS_LUA"
    else
        rm -f "$MONITORS_LUA"
    fi
    hyprctl reload >/dev/null
    menu_notify "Display settings reverted."
    return 1
}

monitor_label() {
    local i=$1
    echo "${M_NAME[$i]}"
}

monitor_state() {
    local i=$1 s
    if ((M_OFF[i])); then echo "off"; return; fi
    if [ -n "${M_MIRROR[$i]}" ]; then echo "mirrors ${M_MIRROR[$i]}"; return; fi
    s=$(awk -v r="${M_REFRESH[$i]}" 'BEGIN { printf "%d", r + 0.5 }')
    s="${M_W[$i]}x${M_H[$i]}@$s · ${M_SCALE[$i]}x"
    case "${M_TRANSFORM[$i]}" in
        1) s+=" · 90°" ;;
        2) s+=" · 180°" ;;
        3) s+=" · 270°" ;;
    esac
    echo "$s"
}

# Menu of unique modes for monitor $1; sets MENU_ID to "WxH@R".
pick_mode() {
    local i=$1 mode seen=" " cur
    cur="${M_W[$i]}x${M_H[$i]}@${M_REFRESH[$i]}"
    menu_reset
    for mode in ${M_MODES[$i]}; do
        mode=$(awk -v m="$mode" 'BEGIN { split(m, a, "@"); printf "%s@%.2f", a[1], a[2] }')
        [[ "$seen" == *" $mode "* ]] && continue
        seen+="$mode "
        menu_add "$mode" "${mode%@*}" "" "$(awk -v r="${mode#*@}" 'BEGIN { printf "%g Hz", r }')$([ "$mode" = "$cur" ] && echo " · current")"
    done
    menu_show "resolution" "${M_NAME[$i]}" "$cur"
}

pick_scale() {
    local i=$1 s
    menu_reset
    for s in 1 1.25 1.5 1.75 2; do
        menu_add "$s" "${s}x" "" "$([ "$s" = "${M_SCALE[$i]}" ] && echo current)"
    done
    menu_show "scale" "${M_NAME[$i]}" "${M_SCALE[$i]}"
}

pick_rotation() {
    local i=$1
    menu_reset
    menu_add 0 "Normal"
    menu_add 1 "Rotate 90°"
    menu_add 2 "Rotate 180°"
    menu_add 3 "Rotate 270°"
    menu_show "rotation" "${M_NAME[$i]}" "${M_TRANSFORM[$i]}"
}

# Place monitor $1 next to another one; sets M_X/M_Y.
place() {
    local i=$1 j rel align="" wm hm wt ht
    menu_reset
    for j in "${!M_NAME[@]}"; do
        ((j == i || M_OFF[j])) && continue
        [ -n "${M_MIRROR[$j]}" ] && continue
        menu_add "right:$j" "Right of ${M_NAME[$j]}"
        menu_add "left:$j" "Left of ${M_NAME[$j]}"
        menu_add "above:$j" "Above ${M_NAME[$j]}"
        menu_add "below:$j" "Below ${M_NAME[$j]}"
    done
    ((${#MENU_IDS[@]} > 0)) || { menu_notify "There's no other active monitor to place it next to."; return 1; }
    menu_show "position" "${M_NAME[$i]}" || return 1
    rel=${MENU_ID%%:*}
    j=${MENU_ID#*:}
    read -r wm hm <<<"$(logical_size "$i")"
    read -r wt ht <<<"$(logical_size "$j")"

    # Only ask for alignment when the edges don't already line up.
    local cross_m cross_t labels
    case "$rel" in
        right | left) cross_m=$hm cross_t=$ht labels=("Top edges" "Centered" "Bottom edges") ;;
        *) cross_m=$wm cross_t=$wt labels=("Left edges" "Centered" "Right edges") ;;
    esac
    align=0
    if ((cross_m != cross_t)); then
        menu_reset
        menu_add 0 "${labels[0]}"
        menu_add 1 "${labels[1]}"
        menu_add 2 "${labels[2]}"
        menu_show "align" "${M_NAME[$i]}" || return 1
        align=$MENU_ID
    fi
    local off=$((align * (cross_t - cross_m) / 2))
    case "$rel" in
        right) M_X[i]=$((M_X[j] + wt)) M_Y[i]=$((M_Y[j] + off)) ;;
        left) M_X[i]=$((M_X[j] - wm)) M_Y[i]=$((M_Y[j] + off)) ;;
        above) M_X[i]=$((M_X[j] + off)) M_Y[i]=$((M_Y[j] - hm)) ;;
        below) M_X[i]=$((M_X[j] + off)) M_Y[i]=$((M_Y[j] + ht)) ;;
    esac
    M_MIRROR[i]=""
}

pick_mirror() {
    local i=$1 j
    menu_reset
    menu_add none "Don't mirror"
    for j in "${!M_NAME[@]}"; do
        ((j == i || M_OFF[j])) && continue
        [ -n "${M_MIRROR[$j]}" ] && continue
        menu_add "${M_NAME[$j]}" "Mirror ${M_NAME[$j]}"
    done
    ((${#MENU_IDS[@]} > 1)) || { menu_notify "There's no other active monitor to mirror."; return 1; }
    menu_show "mirror" "${M_NAME[$i]}"
}

# Mirroring needs a position again once it stops; put it right of the rest.
unmirror() {
    local i=$1 j maxx=0 w h
    for j in "${!M_NAME[@]}"; do
        ((j == i || M_OFF[j])) && continue
        read -r w h <<<"$(logical_size "$j")"
        ((M_X[j] + w > maxx)) && maxx=$((M_X[j] + w))
    done
    M_MIRROR[i]="" M_X[i]=$maxx M_Y[i]=0
}

monitor_menu() {
    local i=$1 selected=""
    while :; do
        menu_reset
        if ((M_OFF[i])); then
            menu_add enable "Enable" check.svg
        else
            menu_add mode "Resolution & Refresh" "" "${M_W[$i]}x${M_H[$i]}@$(awk -v r="${M_REFRESH[$i]}" 'BEGIN { printf "%d", r + 0.5 }')"
            menu_add scale "Scale" "" "${M_SCALE[$i]}x"
            menu_add rotation "Rotation" "" "$(monitor_state "$i" | grep -o '[0-9]*°' || echo none)"
            menu_add position "Position" "" "${M_X[$i]},${M_Y[$i]}"
            menu_add mirror "Mirror" "" "${M_MIRROR[$i]:-off}"
            menu_add disable "Disable" x.svg
        fi
        menu_show "${M_NAME[$i]}" "${M_DESC[$i]}" "$selected" || return 0
        selected=$MENU_ID
        load_monitors
        local changed=0
        case "$MENU_ID" in
            enable) M_OFF[i]=0 M_MIRROR[i]="" M_W[i]=0 changed=1 ;;
            mode) pick_mode "$i" && { M_W[i]=${MENU_ID%%x*}; M_H[i]=${MENU_ID#*x}; M_H[i]=${M_H[i]%@*}; M_REFRESH[i]=${MENU_ID#*@}; changed=1; } ;;
            scale) pick_scale "$i" && { M_SCALE[i]=$MENU_ID; changed=1; } ;;
            rotation) pick_rotation "$i" && { M_TRANSFORM[i]=$MENU_ID; changed=1; } ;;
            position) place "$i" && changed=1 ;;
            mirror)
                if pick_mirror "$i"; then
                    if [ "$MENU_ID" = none ]; then unmirror "$i"; else M_MIRROR[i]=$MENU_ID; fi
                    changed=1
                fi ;;
            disable)
                if (($(enabled_count) < 2)); then
                    menu_notify "That's the only active monitor; disabling it would leave no display." critical
                else
                    confirm "Disable ${M_NAME[$i]}?" Disable && { M_OFF[i]=1; changed=1; }
                fi ;;
        esac
        if ((changed)); then
            normalize_positions
            apply || true
            load_monitors
        fi
    done
}

main_menu() {
    local selected="" i
    while :; do
        load_monitors
        menu_reset
        for i in "${!M_NAME[@]}"; do
            menu_add "m$i" "$(monitor_label "$i")" devices.svg "$(monitor_state "$i")"
        done
        [ -f "$MONITORS_LUA" ] && menu_add reset "Reset to Automatic" refresh.svg
        local mesg=""
        grep -qs 'hl\.monitor' "$LOCAL_LUA" && mesg="local.lua has monitor rules; they override these settings."
        menu_show displays "$mesg" "$selected" || return 0
        selected=$MENU_ID
        case "$MENU_ID" in
            reset)
                confirm "Remove saved display settings and use Hyprland's automatic layout?" Reset &&
                    { rm -f "$MONITORS_LUA"; hyprctl reload >/dev/null; } ;;
            m*) monitor_menu "${MENU_ID#m}" ;;
        esac
    done
}

if [ "${1:-}" = "--print" ]; then
    load_monitors
    generate
    exit 0
fi

main_menu
